/**
 * web 侧也要认得 `className`(2026-10-31)。
 *
 * 成因:`app/(pilot)/shared-pilot/page.tsx` 经 `@ihui/rn-app/pilot` 把共享 RN 屏渲染到 web
 * (react-native-web 试点),于是 `packages/ui-native` 的源码进入 **web 的 tsc 程序**;
 * 而那些组件用 nativewind 的 `className` 书写 —— 该 prop 由 `nativewind/types` 的模块增强提供,
 * web 程序此前没加载它 ⇒ `next build` 在 `vip-badge.tsx` 等文件上报 TS2769
 * (`Property 'className' does not exist on type 'TextProps'`),整轮构建失败。
 *
 * 这与 RN 端 `apps/mobile-rn/nativewind-env.d.ts` 是同一件事、同一份来源:两端各自把自己的
 * 类型程序接上 nativewind 的增强,不复制任何映射表。只影响类型,运行期仍走 react-native-web。
 */
import 'nativewind/types'
// ⁠​‌​​‌​​‌‍‍​‌​​‌​​​‍‍​‌​‌​‌​‌‍‍​‌​​‌​​‌‍‍​​‌​‌‌​‌‍‍​‌​​​​​‌‍‍​‌​​‌​​‌‍‍‌​‌‌​‌‌‌‍‍‌‌​​‌‌​​‌‌‌‌​‌​‍‍‌‌​‌‌​​​‌​​​‌‌‌‍‍​‌​​​​​‌‍‍​‌​​‌​​‌‍‍‌​‌‌​‌‌‌‍‍‌‌​​‌‌‌​‌​​‌‌‌​‍‍‌‌​​‌‌​​​‌​​‌​‌‍‍‌​‌‌‌​‌‌‌​‌‌‌​‌‍‍‌​‌‌​‌‌‌‍‍​‌​​‌‌​​‍‍​‌​​​​‌‌‍‍‌​‌‌​‌‌‌‍‍​‌‌​​​​‌‍‍​‌‌​‌​​‌‍‍​‌‌‌‌​‌​‍‍​‌‌​‌​​​‍‍​‌‌‌​​‌‌‍‍​​‌​‌‌‌​‍‍​‌‌‌​‌​​‍‍​‌‌​‌‌‌‌‍‍​‌‌‌​​​​‍‍‌​‌‌​‌‌‌‍‍​‌​‌​​​​‍‍​‌​‌​​‌​‍‍​‌​​‌‌‌‌‍‍​‌​‌​‌‌​‍‍​‌​​​‌​‌‍‍​‌​​‌‌‌​‍‍​‌​​​​​‌‍‍​‌​​‌‌‌​‍‍​‌​​​​‌‌‍‍​‌​​​‌​‌‍‍​​‌​‌‌​‌‍‍​​‌‌​​‌​‍‍​​‌‌​​​​‍‍​​‌‌​​‌​‍‍​​‌‌​‌‌​⁠
